import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { Card, Chip, PageHeader, ResponsiveTable } from '../components/ui';
import { useDemo } from '../context/DemoContext';
const short = (s='') => { const [a,b='']=s.split(' '); return `${a} ${b.charAt(0)}.`; };
export default function ChecklistsPage(){ const {checklists,tasks,role,roleId}=useDemo(); const [phase,setPhase]=useState('all'); const [discipline,setDiscipline]=useState('all'); const [view,setView]=useState('all'); const worker=['installer','fabWorker','workshop','designer','contractor'].includes(roleId); const mine=short(role.name); const rows=useMemo(()=>{const base=checklists.map(c=>({...c,task:tasks.find(t=>t.id===c.taskId)})).filter(c=>c.task).filter(c=>!worker||c.person===mine).filter(c=>phase==='all'||(phase==='pre'?Boolean(c.steps?.pre1||c.steps?.pre2):Boolean(c.steps?.post1||c.steps?.post2))).filter(c=>discipline==='all'||c.task.kind===discipline);if(view==='pm')return tasks.filter(t=>t.kind==='install'&&t.stage==='Manager Review'&&(discipline==='all'||discipline==='install')).map(t=>({id:`pm-${t.id}`,task:t,person:'Project Manager',role:'PM',steps:{},status:'Awaiting review'}));return base.filter(c=>view==='all'||(view==='tl'?c.role==='TL':c.role==='TM'));},[checklists,tasks,worker,mine,phase,discipline,view]); const cols=[{key:'task',label:'Task',primary:true,render:c=><div className="stack"><strong>{c.task.name}</strong><small><Link className="job-link" to={`/jobs/${c.task.jobId}`}>{c.task.jobId}</Link> · {c.task.kind}</small></div>},{key:'phase',label:'Phase',render:c=>c.role==='PM'?'PM review':c.steps?.post1||c.steps?.post2?'Post-job':'Pre-job'},{key:'person',label:'Assigned to'},{key:'role',label:'View',render:c=>c.role==='TL'?'Team leader':c.role==='TM'?'Team member':c.role||'PM review'},{key:'status',label:'Status',render:c=><Chip value={c.status|| (c.steps?.post2||c.steps?.pre2?'Completed':'In Progress')}/>},{key:'hours',label:'Hours',render:c=>c.steps?.post2?.hours?`${c.steps.post2.hours}h`:'-'},{key:'action',label:'Open',render:c=><Link className="btn btn-ghost btn-sm" to={`/jobs/${c.task.jobId}`}>Open job</Link>}]; return <div className="dash"><PageHeader eyebrow="Field operations" title={worker?'My checklists':'Checklists'} subtitle={`${rows.length} checklist records`} /><div className="filters"><label className="filter-select"><span>Phase</span><select value={phase} onChange={e=>setPhase(e.target.value)}><option value="all">All phases</option><option value="pre">Pre-job</option><option value="post">Post-job</option></select></label><label className="filter-select"><span>Discipline</span><select value={discipline} onChange={e=>setDiscipline(e.target.value)}><option value="all">All</option><option value="design">Design</option><option value="fab">Fabrication</option><option value="install">Install</option></select></label>{!worker&&<label className="filter-select"><span>Checklist view</span><select value={view} onChange={e=>setView(e.target.value)}><option value="all">All roles</option><option value="pm">PM review</option><option value="tl">Team leader</option><option value="tm">Team member</option></select></label>}</div><Card title="Checklist register" flush><ResponsiveTable columns={cols} rows={rows} empty="No checklists match these filters"/></Card></div>; }
